<script setup lang="ts">
import type { CommunityRecord, PurposeData } from '~/types/community'
import { errorMessage } from '~/utils/format'
const { purposes, loadPurposes } = usePurposeCatalog()
const { bootstrap } = useAppData()
const styles = ref<CommunityRecord<{icon:string}>[]>([]), error=ref(''),busy=ref(false),open=ref(false),current=ref<CommunityRecord<PurposeData>|null>(null)
const name=ref(''),icon=ref('📌'),profile=ref<PurposeData['profile']>('general')
const profiles=[{label:'通用信息',value:'general'},{label:'经营、生产',value:'business'},{label:'仓库存放',value:'storage'},{label:'出租、居住',value:'housing'}]
async function load(){try{await loadPurposes();styles.value=await $fetch('/api/records/point-style')}catch(e){error.value=errorMessage(e)}}
function edit(record?:CommunityRecord<PurposeData>){current.value=record??null;name.value=record?.name??'';icon.value=record?.data.icon??'📌';profile.value=record?.data.profile??'general';open.value=true}
async function save(){if(!name.value.trim()||!icon.value.trim())return;busy.value=true;error.value='';try{await $fetch(current.value?`/api/records/purpose-type/${current.value.id}`:'/api/records/purpose-type',{method:current.value?'PUT':'POST',body:{name:name.value,parentId:'',data:{icon:icon.value,profile:profile.value},revision:current.value?.revision??0,archived:current.value?.archived??false},retry:0});open.value=false;await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function toggle(record:CommunityRecord<PurposeData>){busy.value=true;try{await $fetch(`/api/records/purpose-type/${record.id}`,{method:'PUT',body:{...record,archived:!record.archived},retry:0});await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
async function saveIcon(typeId:string,typeName:string,value:string){busy.value=true;error.value='';const style=styles.value.find(x=>x.parentId===typeId);try{await $fetch(style?`/api/records/point-style/${style.id}`:'/api/records/point-style',{method:style?'PUT':'POST',body:{name:typeName,parentId:typeId,data:{icon:value},revision:style?.revision??0},retry:0});await load()}catch(e){error.value=errorMessage(e)}finally{busy.value=false}}
onMounted(load)
</script>
<template><section class="panel panel-body space-y-4"><UAlert v-if="error" :description="error" color="error" /><div class="flex justify-between items-center"><h2 class="section-title">用途分类与图标</h2><UButton label="新增用途" icon="i-lucide-plus" @click="edit()" /></div><p class="text-sm text-muted">每个用途位置选择一种用途。信息类型决定登记时显示哪些字段。</p><div v-for="item in purposes" :key="item.id" class="flex gap-3 items-center border-b border-default pb-2"><span class="text-2xl">{{ item.data.icon }}</span><span class="flex-1">{{ item.name }}<small class="block text-muted">{{ profiles.find(x=>x.value===item.data.profile)?.label }} {{ item.archived?'· 已停用':'' }}</small></span><UButton label="编辑" size="sm" variant="outline" :disabled="busy" @click="edit(item)" /><UButton :label="item.archived?'恢复':'停用'" size="sm" color="neutral" variant="ghost" :disabled="busy" @click="toggle(item)" /></div><h2 class="section-title pt-3">场所形态图标</h2><p class="text-sm text-muted">地图默认显示场所形态图标，按用途筛选时显示所选用途图标。</p><div v-for="type in bootstrap?.pointTypes" :key="type.id" class="flex gap-3 items-center"><span class="flex-1">{{ type.name }}</span><UInput :model-value="styles.find(x=>x.parentId===type.id)?.data.icon??(type.name.includes('地')?'🏞️':'🏢')" :maxlength="16" class="w-24" :aria-label="`${type.name}图标`" :disabled="busy" @change="event=>saveIcon(type.id,type.name,(event.target as HTMLInputElement).value)" /></div></section><UModal v-model:open="open" :title="current?'编辑用途':'新增用途'"><template #body><div class="space-y-3"><UAlert v-if="error" :description="error" color="error" /><UFormField label="用途名称" required><UInput v-model="name" class="w-full" /></UFormField><UFormField label="地图图标（Emoji）" required><UInput v-model="icon" :maxlength="16" class="w-full" /><div class="flex gap-2 flex-wrap mt-2"><button v-for="emoji in ['🏪','🏠','🏭','📦','🔑','🏢','🌳','🅿️','🏞️','📌']" :key="emoji" class="text-2xl p-1" @click="icon=emoji">{{ emoji }}</button></div></UFormField><UFormField label="填写的信息类型"><USelect v-model="profile" :items="profiles" class="w-full" /></UFormField></div></template><template #footer><UButton label="保存" :loading="busy" @click="save" /></template></UModal></template>
